import { getPersistedSessions } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
jest.mock('@proton/shared/lib/authentication/persistedSessionStorage', () => ({
    getPersistedSessions: jest.fn(),
}));

const mockedGetPersistedSessions = jest.mocked(getPersistedSessions);
const mockedSendErrorReport = jest.mocked(sendErrorReport);

const session = (localID: number, UID: string, persistedAt: number) =>
    ({ localID, UID, persistedAt }) as ReturnType<typeof getPersistedSessions>[number];

describe('getLastActivePersistedUserSession', () => {
    beforeEach(() => {
        jest.clearAllMocks();
    });

    it('returns null when there are no persisted sessions', () => {
        mockedGetPersistedSessions.mockReturnValue([]);
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).not.toHaveBeenCalled();
    });

    it('returns the complete latest valid session across apps', () => {
        const older = session(123, 'older', 100);
        const latest = session(456, 'latest', 300);
        const middle = session(789, 'middle', 200);
        mockedGetPersistedSessions.mockReturnValue([older, latest, middle]);
        expect(getLastActivePersistedUserSession()).toBe(latest);
    });

    it('skips sessions without a UID or valid timestamp', () => {
        const valid = session(123, 'valid', 100);
        mockedGetPersistedSessions.mockReturnValue([session(456, '', 300), session(789, 'invalid', NaN), valid]);
        expect(getLastActivePersistedUserSession()).toBe(valid);
    });

    it('reports storage or parsing failures and returns null', () => {
        mockedGetPersistedSessions.mockImplementation(() => {
            throw new Error('Storage unavailable');
        });
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.objectContaining({ name: 'Error' }));
    });
});
